/* =====================================================================
   054_iso_27001_obligations.sql

   Bulk load of the ISO/IEC 27001:2022 Obligation catalogue.

   Source : Import ISO 27001 Sample data v1.0.xlsx
              sheet 'State Obligations'      -> 251 rows
              sheet 'Execution Obligations'  -> 291 rows
              sheet 'Assurance Obligations'  -> 16 rows
              -------------------------------------------
                                                558 Obligations

   Writes to:
     GRAC_New.requirement_obligation                  parent row, one per sheet row
     GRAC_New.obligation_state_rule                   State detail      (251)
     GRAC_New.obligation_execution_spec               Execution detail  (291)
     GRAC_New.obligation_assurance_spec               Assurance detail  (16)
     GRAC_New.requirement_obligation_evidence         one evidence spec per Obligation
     GRAC_New.obligation_*_evidence_link              type-specific link to that spec
     GRAC_New.obligation_requirement_release_map      Practice + Release + Statement link

   Prerequisites : 026 (taxonomy schema), 027 (type master seed),
                   033 (event types + trigger mode), 052 (statements),
                   053 (Practices + Statement mapping). 053 MUST have run:
                   every Obligation resolves its Practice by Practice Name.
   Rerunnable    : yes. An Obligation whose Obligation Name already exists
                   is skipped whole -- parent, detail, evidence and mapping.
   Rollback      : 054_iso_27001_obligations_rollback.sql

   FILE ENCODING
   -------------
   Saved as UTF-8 with BOM. Several texts contain U+2019 (right single
   quotation mark, as in "organisation's"). Open in SSMS normally, or run
   with: sqlcmd -f 65001 -i 054_iso_27001_obligations.sql
   All literals are N'' prefixed and embedded apostrophes are doubled.

   HOW A STATEMENT IS RESOLVED
   ---------------------------
   Not by looking the control up again. The Obligation sheets carry no
   framework_statement_id column, and re-deriving one from 'Control No. and
   Name' would let 054 disagree with 053 about which Statement a Practice
   belongs to.

   Instead each Obligation inherits the Statement from the Practice mapping
   053 already wrote: framework_statement_requirement_map gives the
   (Practice -> Statement) pair, and 054 records that same Statement on the
   Obligation's own mapping row. Whichever resolution mode 053 ran in --
   sheet framework_statement_id or control reference -- 054 follows it.

   The sheet's 'Control No. and Name' is still parsed and cross-checked
   against the mapped Statement's statement_reference, so a Practice that
   ended up under the wrong control stops the load rather than propagating.

   HOW AN OBLIGATION IS IDENTIFIED
   -------------------------------
   By obligation_name. requirement_obligation has no code column, and all
   558 Obligation Names in the workbook are distinct, so the name is the
   natural key for the skip test and for rejoining an inserted parent to
   its detail row.

   The sheet's own 'Obligation ID' (OBL-POL-001 ...) is NOT stored as a key
   -- there is no column for it -- and it could not be one anyway: nine IDs
   are reused across unrelated controls, a consequence of the same Practice
   ID reuse documented in 053 --

       OBL-AUT-001  OBL-AUT-002  OBL-AUT-003     A.5.5  vs A.5.17
       OBL-DSP-001  OBL-DSP-002  OBL-DSP-003
       OBL-DSP-011  OBL-DSP-012  OBL-DSP-013     A.6.4  vs A.7.14

   It is preserved in requirement_obligation.remarks so any row can be
   traced back to the spreadsheet.

   ASSURANCE TRIGGER: WHY THE SHEET'S EVENT COLUMN IS NOT ALWAYS LOADED
   --------------------------------------------------------------------
   The Assurance sheet fills 'Event Domain' and 'Event' on all 16 rows,
   including the 13 that are Scheduled. obligation_assurance_spec
   carries CHECK constraint ck_cm_assurance_spec_trigger (migration 033):

       trigger_mode NULL         -> event_type_id must be NULL
       'Scheduled'               -> event_type_id must be NULL
       'EventDriven'             -> event_type_id must be NOT NULL

   A Scheduled assurance therefore cannot carry an event, and inserting one
   would fail the constraint rather than being silently dropped. So:

     * Scheduled rows  -> trigger_mode = 'Scheduled', event_type_id = NULL,
                          and the sheet's Domain/Event wording is preserved
                          verbatim in obligation_assurance_spec.remarks. It
                          is descriptive text ("Authority contact review"),
                          not a lifecycle event, so nothing is lost.
     * EventDriven rows -> event_type_id resolved from event_type_master by
                          matching the sheet's Event against a leaf event
                          name under the domain root named by Event Domain.
                          The 3 EventDriven rows resolve to Onboarding,
                          Offboarding and Commissioning. A row whose event
                          does not resolve aborts the load -- see validation
                          step 6 -- rather than loading half-classified.

   Note on Asset events: 033 seeds the ASSET domain Inactive because no
   asset register existed; 042 activates it. If 042 has not been applied,
   validation step 6 reports the Asset event as unusable and the load stops.

   MAKER-CHECKER
   -------------
   'obligations' is registered with is_maker_checker = 1, so interactive
   saves route through change_management. This script is a controlled bulk
   load and writes directly, exactly as 052 and 053 do. An audit_trace row
   is written per inserted Obligation.

   COLUMN MAPPING WORTH KNOWING
   ----------------------------
     Obligation Name        -> requirement_obligation.obligation_name
     Obligation Description -> requirement_obligation.obligation_text
     load provenance        -> requirement_obligation.remarks

   REQUIRES MIGRATION 055. Before 055, obligation_text was a mirror of
   obligation_name -- cm_manage_repository overwrote it on every save and no
   screen displayed it, so a description written here survived only until
   somebody opened the Obligation and clicked Save. 055 binds the Obligation
   Master form's new Obligation Description box to that column and stops the
   save path from clobbering it. Run 055 before this script; the preflight
   below checks for it.

   remarks carries the load provenance instead -- which sheet row produced
   this Obligation. 055 removed remarks from the form and COALESCEs it on
   update, so that line is back-end only and an interactive save cannot
   blank it.

   NOT SUPPLIED BY THE SHEET
   -------------------------
   execution_frequency_id : the Execution sheet carries a due-by phrase, not
                            a frequency. Left NULL.
   evidence frequency     : left NULL on requirement_obligation_evidence.
   retention_requirement  : the workbook has no retention column. Left NULL.
   severity / mandatory   : not on requirement_obligation. n/a.
   ===================================================================== */

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

-- ---------------------------------------------------------------
-- Clear stale temp tables -- SEPARATE BATCH, ON PURPOSE
--
-- # temp tables live for the whole session, not the script. If an earlier
-- run of a different revision of this file left #obl, #state, #exec, #assur or #key behind
-- with different columns, SQL Server binds the INSERT statements further
-- down against THAT table when it compiles the batch -- before the
-- CREATE TABLE below has had a chance to run -- and the load dies with
-- "Invalid column name" on a column this file plainly declares.
--
-- The GO after this block is what fixes it: the drops complete in their
-- own batch, so the batch that follows compiles against nothing and the
-- CREATE TABLE statements define the shape. Do not fold these drops into
-- the main batch, and do not rely on reconnecting instead.
-- ---------------------------------------------------------------
IF OBJECT_ID('tempdb..#obl')   IS NOT NULL DROP TABLE #obl;
IF OBJECT_ID('tempdb..#state') IS NOT NULL DROP TABLE #state;
IF OBJECT_ID('tempdb..#exec')  IS NOT NULL DROP TABLE #exec;
IF OBJECT_ID('tempdb..#assur') IS NOT NULL DROP TABLE #assur;
IF OBJECT_ID('tempdb..#key')   IS NOT NULL DROP TABLE #key;
GO

BEGIN TRY
BEGIN TRANSACTION;

-- ---------------------------------------------------------------
-- Configuration
-- ---------------------------------------------------------------
DECLARE @by NVARCHAR(100) = N'anoop.ps@soffit.in';

DECLARE @release_id BIGINT;
DECLARE @type_state BIGINT, @type_exec BIGINT, @type_assur BIGINT;
DECLARE @ins_obl INT = 0, @ins_state INT = 0, @ins_exec INT = 0, @ins_assur INT = 0;
DECLARE @ins_evid INT = 0, @ins_link INT = 0, @ins_map INT = 0;
DECLARE @missing NVARCHAR(4000), @error NVARCHAR(4000);

-- ---------------------------------------------------------------
-- Preflight
-- ---------------------------------------------------------------
IF SCHEMA_ID('GRAC_New') IS NULL
    THROW 50400, 'Schema GRAC_New is missing. Run 001 first.', 1;
IF OBJECT_ID('GRAC_New.requirement_obligation','U') IS NULL
    THROW 50401, 'GRAC_New.requirement_obligation is missing. Run 001 and 019 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_type_master','U') IS NULL
    THROW 50402, 'GRAC_New.obligation_type_master is missing. Run 026 and 027 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_state_rule','U') IS NULL
    THROW 50403, 'GRAC_New.obligation_state_rule is missing. Run 026 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_execution_spec','U') IS NULL
    THROW 50404, 'GRAC_New.obligation_execution_spec is missing. Run 026 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_assurance_spec','U') IS NULL
    THROW 50405, 'GRAC_New.obligation_assurance_spec is missing. Run 026 first.', 1;
IF OBJECT_ID('GRAC_New.event_type_master','U') IS NULL
    THROW 50406, 'GRAC_New.event_type_master is missing. Run 033 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_requirement_release_map','U') IS NULL
    THROW 50407, 'GRAC_New.obligation_requirement_release_map is missing. Run 019 and 021 first.', 1;
IF COL_LENGTH('GRAC_New.obligation_requirement_release_map','framework_statement_id') IS NULL
    THROW 50408, 'obligation_requirement_release_map.framework_statement_id is missing. Run 021 first.', 1;
IF COL_LENGTH('GRAC_New.obligation_assurance_spec','trigger_mode') IS NULL
    THROW 50409, 'obligation_assurance_spec.trigger_mode is missing. Run 033 first.', 1;

-- 055 binds obligation_text to the Obligation Description box and stops
-- cm_manage_repository overwriting it with the name. Without it, every
-- description this script writes is lost the first time somebody saves the
-- Obligation from the screen -- silently, with no error. Detected by looking
-- for the payload member 055 added to the save branch.
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m
              WHERE m.object_id = OBJECT_ID('dbo.cm_manage_repository')
                AND m.definition LIKE N'%@obm_obligation_text%')
    THROW 50421, 'Migration 055_obligation_description_field.sql has not been applied. Run it first, or the Obligation Descriptions loaded here will be overwritten on the first interactive save.', 1;

-- ---------------------------------------------------------------
-- Staging
--
-- #obl holds every sheet row from all three sheets; obl_type is the
-- discriminator and seq is the join key to the per-type tables below.
-- ---------------------------------------------------------------

CREATE TABLE #obl(
  seq                  INT           NOT NULL PRIMARY KEY,
  obl_type             NVARCHAR(40)  NOT NULL,
  statement_reference  NVARCHAR(160) NOT NULL,
  practice_name        NVARCHAR(300) NOT NULL,
  sheet_obligation_id  NVARCHAR(60)  NOT NULL,
  obligation_name      NVARCHAR(500) NOT NULL,
  obligation_desc      NVARCHAR(MAX) NULL,   -- sheet 'Obligation Description' -> requirement_obligation.obligation_text
  evidence_type_name   NVARCHAR(160) NULL,
  evidence_details     NVARCHAR(MAX) NULL);

CREATE TABLE #state(
  seq        INT           NOT NULL PRIMARY KEY,
  attribute  NVARCHAR(250) NOT NULL,
  operator   NVARCHAR(30)  NOT NULL,
  value      NVARCHAR(500) NOT NULL,
  unit       NVARCHAR(50)  NULL,
  tolerance  NVARCHAR(200) NULL);

CREATE TABLE #exec(
  seq                INT            NOT NULL PRIMARY KEY,
  action             NVARCHAR(1000) NOT NULL,
  trigger_condition  NVARCHAR(500)  NULL,
  responsible_party  NVARCHAR(250)  NULL,
  due_within         NVARCHAR(120)  NULL);

CREATE TABLE #assur(
  seq                 INT           NOT NULL PRIMARY KEY,
  verification_method NVARCHAR(500) NOT NULL,
  scope               NVARCHAR(500) NULL,
  assurance_party     NVARCHAR(250) NULL,
  trigger_mode        NVARCHAR(20)  NULL,
  event_domain        NVARCHAR(120) NULL,
  event_name          NVARCHAR(120) NULL,
  frequency_value     NVARCHAR(60)  NULL);

