CREATE INDEX ix_obl_name ON #obl(obligation_name);
CREATE INDEX ix_obl_prac ON #obl(practice_name);

-- ---------------------------------------------------------------
-- Validation
-- ---------------------------------------------------------------
-- 1. Obligation Name must be unique inside the workbook -- it is the
--    natural key for the skip test and for the detail rejoin.
IF EXISTS(SELECT 1 FROM #obl GROUP BY obligation_name HAVING COUNT(*) > 1)
BEGIN
  SET @missing = STUFF((SELECT DISTINCT N', ' + obligation_name FROM #obl
                        GROUP BY obligation_name HAVING COUNT(*) > 1
                        FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Duplicate Obligation Name(s) in the workbook: ', @missing, N'.');
  THROW 50410, @error, 1;
END

-- 2. Every Practice must exist. 053 loads them; a miss means 053 was not
--    run, or a Practice was renamed after it was.
IF EXISTS(SELECT 1 FROM #obl o
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r
                           WHERE r.requirement_name = o.practice_name))
BEGIN
  SET @missing = STUFF((
    SELECT DISTINCT N', ' + o.practice_name FROM #obl o
    WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r
                     WHERE r.requirement_name = o.practice_name)
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Practice(s) not found: ', @missing,
                      N'. Run 053_iso_27001_practices.sql first and do not rename loaded Practices.');
  -- THROW, not RAISERROR: it reaches the CATCH block below, which rolls
  -- the transaction back. RAISERROR would leave it open.
  THROW 50411, @error, 1;
END

-- 2b. Neither requirement_name nor obligation_name is unique in the
--     database, only in the workbook. If either already resolves to two
--     rows the joins below would fan out, so stop rather than guess.
--
--     The row set being counted is the DATABASE table alone, narrowed with
--     EXISTS. Joining #obl here instead would multiply each requirement row
--     by its obligation count, and every Practice carrying two or more
--     Obligations -- which is most of them -- would be reported as a
--     duplicate that does not exist.
IF EXISTS(SELECT 1
          FROM GRAC_New.requirement r
          WHERE EXISTS(SELECT 1 FROM #obl o WHERE o.practice_name = r.requirement_name)
          GROUP BY r.requirement_name HAVING COUNT(*) > 1)
BEGIN
  SET @missing = STUFF((
    SELECT N', ' + x.requirement_name
    FROM (SELECT r.requirement_name
          FROM GRAC_New.requirement r
          WHERE EXISTS(SELECT 1 FROM #obl o WHERE o.practice_name = r.requirement_name)
          GROUP BY r.requirement_name HAVING COUNT(*) > 1) x
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Practice Name(s) present more than once in GRAC_New.requirement: ', @missing,
                      N'. Resolve the duplicates first -- the Obligation load keys on the name.');
  THROW 50418, @error, 1;
END

IF EXISTS(SELECT 1
          FROM GRAC_New.requirement_obligation ro
          WHERE EXISTS(SELECT 1 FROM #obl o WHERE o.obligation_name = ro.obligation_name)
          GROUP BY ro.obligation_name HAVING COUNT(*) > 1)
BEGIN
  SET @missing = STUFF((
    SELECT N', ' + x.obligation_name
    FROM (SELECT ro.obligation_name
          FROM GRAC_New.requirement_obligation ro
          WHERE EXISTS(SELECT 1 FROM #obl o WHERE o.obligation_name = ro.obligation_name)
          GROUP BY ro.obligation_name HAVING COUNT(*) > 1) x
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Obligation Name(s) present more than once in GRAC_New.requirement_obligation: ', @missing,
                      N'. Resolve the duplicates first -- the load keys on the name.');
  THROW 50419, @error, 1;
END

-- 3. Each Practice must already be mapped to the Statement named by the
--    sheet's control. 053 writes that mapping; a miss means 053 was not
--    run for this control, or the Practice sits under a different one.
IF EXISTS(SELECT 1 FROM #obl o
          JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
          WHERE NOT EXISTS(
            SELECT 1
            FROM GRAC_New.framework_statement_requirement_map m
            JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
            WHERE m.requirement_id = r.requirement_id
              AND m.status = N'Active'
              AND fs.statement_reference = o.statement_reference))
BEGIN
  SET @missing = STUFF((
    SELECT DISTINCT N', ' + o.practice_name + N' -> ' + o.statement_reference
    FROM #obl o
    JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
    WHERE NOT EXISTS(
      SELECT 1
      FROM GRAC_New.framework_statement_requirement_map m
      JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
      WHERE m.requirement_id = r.requirement_id
        AND m.status = N'Active'
        AND fs.statement_reference = o.statement_reference)
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Practice / Statement mapping not found for: ', @missing,
                      N'. Run 053_iso_27001_practices.sql first, and confirm it resolved the Statements as expected.');
  -- THROW, not RAISERROR: it reaches the CATCH block below, which rolls
  -- the transaction back. RAISERROR would leave it open.
  THROW 50412, @error, 1;
END

-- 3b. All of those Statements must sit in one release.
IF (SELECT COUNT(DISTINCT fs.release_id)
    FROM #obl o
    JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
    JOIN GRAC_New.framework_statement_requirement_map m ON m.requirement_id = r.requirement_id AND m.status = N'Active'
    JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
                                        AND fs.statement_reference    = o.statement_reference) > 1
BEGIN
  SET @error = N'The mapped Framework Statements belong to more than one Release. Load one release at a time.';
  THROW 50413, @error, 1;
END

SELECT TOP 1 @release_id = fs.release_id
FROM #obl o
JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
JOIN GRAC_New.framework_statement_requirement_map m ON m.requirement_id = r.requirement_id AND m.status = N'Active'
JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
                                    AND fs.statement_reference    = o.statement_reference;

-- 4. Obligation types.
SELECT @type_state = MAX(CASE WHEN type_code = N'State'     THEN obligation_type_id END),
       @type_exec  = MAX(CASE WHEN type_code = N'Execution' THEN obligation_type_id END),
       @type_assur = MAX(CASE WHEN type_code = N'Assurance' THEN obligation_type_id END)
FROM GRAC_New.obligation_type_master;

IF @type_state IS NULL OR @type_exec IS NULL OR @type_assur IS NULL
BEGIN
  SET @error = N'obligation_type_master is missing one of State / Execution / Assurance. Run 027 first.';
  THROW 50414, @error, 1;
END

-- 5. Evidence types must exist in the master.
IF EXISTS(SELECT 1 FROM #obl o
          WHERE o.evidence_type_name IS NOT NULL
            AND NOT EXISTS(SELECT 1 FROM GRAC_New.evidence_type_master t
                           WHERE t.evidence_type_name = o.evidence_type_name
                             AND t.is_active = 1))
BEGIN
  SET @missing = STUFF((
    SELECT DISTINCT N', ' + o.evidence_type_name FROM #obl o
    WHERE o.evidence_type_name IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM GRAC_New.evidence_type_master t
                     WHERE t.evidence_type_name = o.evidence_type_name AND t.is_active = 1)
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Evidence Type(s) not found or inactive in evidence_type_master: ', @missing, N'.');
  THROW 50415, @error, 1;
END

-- 6. Assurance: frequency must resolve, and an EventDriven row must resolve
--    to an ACTIVE leaf event under the domain root it names.
IF EXISTS(SELECT 1 FROM #assur a
          WHERE a.frequency_value IS NOT NULL
            AND NOT EXISTS(SELECT 1 FROM GRAC_New.reference_option ro
                           WHERE ro.option_group = N'frequency-types'
                             AND ro.status = N'Active'
                             AND ro.option_value = a.frequency_value))
BEGIN
  SET @missing = STUFF((
    SELECT DISTINCT N', ' + a.frequency_value FROM #assur a
    WHERE a.frequency_value IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM GRAC_New.reference_option ro
                     WHERE ro.option_group = N'frequency-types' AND ro.status = N'Active'
                       AND ro.option_value = a.frequency_value)
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Assurance frequency value(s) not in reference_option(frequency-types): ', @missing, N'.');
  THROW 50416, @error, 1;
END

IF EXISTS(SELECT 1 FROM #assur a
          WHERE a.trigger_mode = N'EventDriven'
            AND NOT EXISTS(SELECT 1
                           FROM GRAC_New.event_type_master leaf
                           JOIN GRAC_New.event_type_master root
                             ON root.event_type_id = leaf.parent_event_type_id
                           WHERE leaf.event_name = a.event_name
                             AND root.event_name = a.event_domain
                             AND leaf.status = N'Active'
                             AND root.status = N'Active'))
BEGIN
  SET @missing = STUFF((
    SELECT DISTINCT N', ' + a.event_domain + N' / ' + a.event_name FROM #assur a
    WHERE a.trigger_mode = N'EventDriven'
      AND NOT EXISTS(SELECT 1
                     FROM GRAC_New.event_type_master leaf
                     JOIN GRAC_New.event_type_master root ON root.event_type_id = leaf.parent_event_type_id
                     WHERE leaf.event_name = a.event_name AND root.event_name = a.event_domain
                       AND leaf.status = N'Active' AND root.status = N'Active')
    FOR XML PATH('')), 1, 2, N'');
  SET @error = CONCAT(N'Event-driven Assurance event(s) not found or not Active in event_type_master: ', @missing,
                      N'. Asset events are seeded Inactive by 033 -- run 042_asset_event_types_activate.sql, or correct the sheet.');
  THROW 50417, @error, 1;
END

-- ---------------------------------------------------------------
-- 1. Obligation parent rows
--
-- requirement_id and release_id are the legacy columns 019 made nullable;
-- the authoritative link is obligation_requirement_release_map, written in
-- step 6.  They are still populated because cm_manage_repository writes
-- them and several read paths still select them.
-- ---------------------------------------------------------------
-- WHERE THE SHEET'S OBLIGATION DESCRIPTION LANDS
--
-- obligation_text, which migration 055 turned into the Obligation
-- Description box on the Obligation Master form. Before 055 that column was
-- a mirror of obligation_name and writing a description into it was
-- pointless -- the next interactive save overwrote it.
--
-- remarks takes the load provenance: which sheet row this Obligation came
-- from. 055 dropped remarks from the form and COALESCEs it on update, so it
-- is a back-end field and a user saving the Obligation cannot blank it.
DECLARE @newobl TABLE(obligation_id BIGINT, obligation_name NVARCHAR(500));

INSERT GRAC_New.requirement_obligation
  (requirement_id, release_id, obligation_type_id, obligation_name, obligation_text,
   remarks, status, entered_by)
OUTPUT inserted.obligation_id, inserted.obligation_name INTO @newobl
SELECT r.requirement_id, @release_id,
       CASE o.obl_type WHEN N'State' THEN @type_state
                       WHEN N'Execution' THEN @type_exec
                       ELSE @type_assur END,
       o.obligation_name, o.obligation_desc,
       CONCAT(N'Bulk load 054. Sheet Obligation ID: ', o.sheet_obligation_id,
              N'. Source control: ', o.statement_reference, N'.'),
       N'Active', @by
FROM #obl o
JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement_obligation x
                 WHERE x.obligation_name = o.obligation_name);

SET @ins_obl = @@ROWCOUNT;

-- Resolved key for everything below: sheet row -> obligation_id.
-- framework_statement_id comes from the Practice mapping 053 wrote, not
-- from a fresh reference lookup, so 054 can never disagree with 053 about
-- which Statement a Practice sits under. The statement_reference join is
-- the cross-check described in the header.
SELECT o.seq,
       o.obl_type,
       ro.obligation_id,
       r.requirement_id,
       fs.framework_statement_id
INTO #key
FROM #obl o
JOIN GRAC_New.requirement_obligation ro ON ro.obligation_name = o.obligation_name
JOIN GRAC_New.requirement r             ON r.requirement_name = o.practice_name
JOIN GRAC_New.framework_statement_requirement_map m
                                        ON m.requirement_id = r.requirement_id
                                       AND m.status         = N'Active'
JOIN GRAC_New.framework_statement fs    ON fs.framework_statement_id = m.framework_statement_id
                                       AND fs.statement_reference    = o.statement_reference
                                       AND fs.release_id             = @release_id;
CREATE UNIQUE CLUSTERED INDEX ux_key_seq ON #key(seq);

-- One resolved row per sheet row. Anything else means a Practice is mapped
-- to the same control twice, and the inserts below would fan out.
IF (SELECT COUNT(*) FROM #key) <> (SELECT COUNT(*) FROM #obl)
BEGIN
  SET @error = CONCAT(N'Key resolution produced ', (SELECT COUNT(*) FROM #key),
                      N' rows for ', (SELECT COUNT(*) FROM #obl),
                      N' sheet rows. A Practice resolves to more than one Statement for the same control reference.');
  THROW 50420, @error, 1;
END

-- ---------------------------------------------------------------
-- 2. State detail
-- ---------------------------------------------------------------
INSERT GRAC_New.obligation_state_rule
  (obligation_id, attribute, operator, value, unit, tolerance, status, entered_by)
SELECT k.obligation_id, s.attribute, s.operator, s.value, s.unit, s.tolerance, N'Active', @by
FROM #state s
JOIN #key k ON k.seq = s.seq
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_state_rule x
                 WHERE x.obligation_id = k.obligation_id AND x.status = N'Active');
SET @ins_state = @@ROWCOUNT;

-- ---------------------------------------------------------------
-- 3. Execution detail
--
-- execution_frequency_id stays NULL: the sheet's 'Execution Due Within'
-- is a deadline phrase ("Before approval"), not a recurrence, and it maps
-- to due_within.
-- ---------------------------------------------------------------
INSERT GRAC_New.obligation_execution_spec
  (obligation_id, action, execution_frequency_id, trigger_condition,
   responsible_party, due_within, status, entered_by)
SELECT k.obligation_id, e.action, NULL, e.trigger_condition,
       e.responsible_party, e.due_within, N'Active', @by
FROM #exec e
JOIN #key k ON k.seq = e.seq
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_execution_spec x
                 WHERE x.obligation_id = k.obligation_id AND x.status = N'Active');
SET @ins_exec = @@ROWCOUNT;

-- ---------------------------------------------------------------
-- 4. Assurance detail
--
-- event_type_id is set only for EventDriven rows -- see the header note on
-- ck_cm_assurance_spec_trigger.  For a Scheduled row the sheet's Domain and
-- Event wording is kept in remarks so nothing from the workbook is lost.
-- ---------------------------------------------------------------
INSERT GRAC_New.obligation_assurance_spec
  (obligation_id, verification_method, scope, assurance_frequency_id, assurance_party,
   trigger_mode, event_type_id, remarks, status, entered_by)
SELECT k.obligation_id, a.verification_method, a.scope, ro.reference_option_id, a.assurance_party,
       a.trigger_mode,
       CASE WHEN a.trigger_mode = N'EventDriven' THEN ev.event_type_id ELSE NULL END,
       CASE WHEN a.trigger_mode = N'EventDriven' THEN NULL
            ELSE CONCAT(N'Sheet Assurance Event (not a lifecycle event, retained as text): ',
                        a.event_domain, N' / ', a.event_name, N'.') END,
       N'Active', @by
FROM #assur a
JOIN #key k ON k.seq = a.seq
LEFT JOIN GRAC_New.reference_option ro
       ON ro.option_group = N'frequency-types'
      AND ro.status       = N'Active'
      AND ro.option_value = a.frequency_value
LEFT JOIN (
      SELECT leaf.event_type_id, leaf.event_name, root.event_name AS domain_name
      FROM GRAC_New.event_type_master leaf
      JOIN GRAC_New.event_type_master root ON root.event_type_id = leaf.parent_event_type_id
      WHERE leaf.status = N'Active' AND root.status = N'Active'
) ev ON ev.event_name = a.event_name AND ev.domain_name = a.event_domain
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_assurance_spec x
                 WHERE x.obligation_id = k.obligation_id AND x.status = N'Active');
SET @ins_assur = @@ROWCOUNT;

-- ---------------------------------------------------------------
-- 5. Evidence spec + type-specific link
--
-- The physical evidence row lives in requirement_obligation_evidence
-- (026 kept that table as the single evidence store); the per-type link
-- table records which taxonomy branch owns it.
-- ---------------------------------------------------------------
INSERT GRAC_New.requirement_obligation_evidence
  (obligation_id, evidence_type_id, frequency_id, retention_requirement, remarks, status, entered_by)
SELECT k.obligation_id, t.evidence_type_id, NULL, NULL, o.evidence_details, N'Active', @by
FROM #obl o
JOIN #key k ON k.seq = o.seq
JOIN GRAC_New.evidence_type_master t
  ON t.evidence_type_name = o.evidence_type_name AND t.is_active = 1
WHERE o.evidence_type_name IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM GRAC_New.requirement_obligation_evidence x
                 WHERE x.obligation_id = k.obligation_id
                   AND x.evidence_type_id = t.evidence_type_id
                   AND x.status = N'Active');
SET @ins_evid = @@ROWCOUNT;

INSERT GRAC_New.obligation_state_evidence_link(obligation_id, obligation_evidence_id, status, entered_by)
SELECT k.obligation_id, ev.obligation_evidence_id, N'Active', @by
FROM #key k
JOIN GRAC_New.requirement_obligation_evidence ev
  ON ev.obligation_id = k.obligation_id AND ev.status = N'Active'
WHERE k.obl_type = N'State'
  AND NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_state_evidence_link x
                 WHERE x.obligation_id = k.obligation_id
                   AND x.obligation_evidence_id = ev.obligation_evidence_id
                   AND x.status = N'Active');
SET @ins_link = @@ROWCOUNT;

INSERT GRAC_New.obligation_execution_evidence_link(obligation_id, obligation_evidence_id, status, entered_by)
SELECT k.obligation_id, ev.obligation_evidence_id, N'Active', @by
FROM #key k
JOIN GRAC_New.requirement_obligation_evidence ev
  ON ev.obligation_id = k.obligation_id AND ev.status = N'Active'
WHERE k.obl_type = N'Execution'
  AND NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_execution_evidence_link x
                 WHERE x.obligation_id = k.obligation_id
                   AND x.obligation_evidence_id = ev.obligation_evidence_id
                   AND x.status = N'Active');
SET @ins_link = @ins_link + @@ROWCOUNT;

INSERT GRAC_New.obligation_assurance_evidence_link(obligation_id, obligation_evidence_id, status, entered_by)
SELECT k.obligation_id, ev.obligation_evidence_id, N'Active', @by
FROM #key k
JOIN GRAC_New.requirement_obligation_evidence ev
  ON ev.obligation_id = k.obligation_id AND ev.status = N'Active'
WHERE k.obl_type = N'Assurance'
  AND NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_assurance_evidence_link x
                 WHERE x.obligation_id = k.obligation_id
                   AND x.obligation_evidence_id = ev.obligation_evidence_id
                   AND x.status = N'Active');
SET @ins_link = @ins_link + @@ROWCOUNT;

-- ---------------------------------------------------------------
-- 6. Obligation -> Practice + Release + Statement mapping
--
-- This is the authoritative link (019 decoupled the parent, 021 added the
-- Statement column).  Uniqueness is the 4-tuple
-- (requirement_id, release_id, framework_statement_id, obligation_id).
-- ---------------------------------------------------------------
INSERT GRAC_New.obligation_requirement_release_map
  (obligation_id, requirement_id, release_id, framework_statement_id, status, entered_by)
SELECT k.obligation_id, k.requirement_id, @release_id, k.framework_statement_id, N'Active', @by
FROM #key k
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_requirement_release_map m
                 WHERE m.obligation_id          = k.obligation_id
                   AND m.requirement_id         = k.requirement_id
                   AND m.release_id             = @release_id
                   AND m.framework_statement_id = k.framework_statement_id);
SET @ins_map = @@ROWCOUNT;

-- Re-activate mappings a previous rollback retired, so a rollback-then-
-- reload round trip is clean.
UPDATE m
   SET m.status = N'Active', m.updated_by = @by, m.updated_dt = SYSUTCDATETIME()
FROM GRAC_New.obligation_requirement_release_map m
JOIN #key k ON k.obligation_id = m.obligation_id
           AND k.requirement_id = m.requirement_id
           AND k.framework_statement_id = m.framework_statement_id
WHERE m.release_id = @release_id AND m.status <> N'Active';

-- ---------------------------------------------------------------
-- Audit trail
--
-- Mirrors the three-table shape cm_manage_repository writes, so these
-- rows render on the Audit Trace screen like any other Add:
--   audit_trace_event  -> one event per Obligation
--   audit_trace_detail -> field-level values for that event
--   audit_trace        -> the flat row, linked by audit_event_id
-- action_type is 'Add' to stay inside the existing vocabulary.
-- ---------------------------------------------------------------
DECLARE @events TABLE(audit_event_id BIGINT, entity_id BIGINT);

INSERT GRAC_New.audit_trace_event
  (entity_type,entity_id,action_type,table_name,record_reference,remarks,before_json,after_json,status,entered_by)
OUTPUT inserted.audit_event_id, inserted.entity_id INTO @events
SELECT N'obligations', k.obligation_id, N'Add',
       N'GRAC_New.requirement_obligation',
       CONCAT(o.sheet_obligation_id, N' - ', o.obligation_name),
       CONCAT(N'Bulk load: migration 054, Import ISO 27001 Sample data v1.0.xlsx, sheet ',
              o.obl_type, N' Obligations.'),
       NULL,
       (SELECT ro.obligation_name name, ro.obligation_text description,
               o.obl_type obligationType, r.requirement_code practiceCode,
               r.requirement_name practiceName, o.statement_reference statementReference,
               ro.status
        FROM GRAC_New.requirement_obligation ro
        JOIN GRAC_New.requirement r ON r.requirement_id = k.requirement_id
        WHERE ro.obligation_id = k.obligation_id
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       N'Active', @by
FROM #key k
JOIN #obl o ON o.seq = k.seq
-- Only the rows this run actually created. @newobl holds exactly those,
-- captured by the OUTPUT clause above -- a far tighter test than pattern
-- matching on a column the user can edit, and it cannot mistake an
-- Obligation someone entered by hand for one this load inserted.
JOIN @newobl nb ON nb.obligation_id = k.obligation_id;

INSERT GRAC_New.audit_trace_detail(audit_event_id,field_name,old_value,new_value,entered_by)
SELECT e.audit_event_id, d.field_name, NULL, d.new_value, @by
FROM @events e
JOIN GRAC_New.requirement_obligation ro ON ro.obligation_id = e.entity_id
LEFT JOIN GRAC_New.obligation_type_master tm ON tm.obligation_type_id = ro.obligation_type_id
CROSS APPLY (VALUES
  (N'Obligation Name',        ro.obligation_name),
  (N'Obligation Description', ro.obligation_text),
  (N'Obligation Type',        tm.type_name),
  (N'Remarks',                ro.remarks),
  (N'Status',                 ro.status)
) AS d(field_name, new_value)
WHERE d.new_value IS NOT NULL;

INSERT GRAC_New.audit_trace
  (audit_event_id,entity_type,entity_id,action_type,table_name,record_reference,remarks,after_json,status,entered_by)
SELECT ev.audit_event_id, ev.entity_type, ev.entity_id, ev.action_type, ev.table_name,
       ev.record_reference, ev.remarks, ev.after_json, N'Active', @by
FROM GRAC_New.audit_trace_event ev
JOIN @events e ON e.audit_event_id = ev.audit_event_id;

COMMIT TRANSACTION;

PRINT CONCAT(N'054 complete. Release ', @release_id,
             N' | Obligations inserted ', @ins_obl,
             N' of 558 (skipped ', 558 - @ins_obl, N' already present)',
             N' | State ', @ins_state,
             N' | Execution ', @ins_exec,
             N' | Assurance ', @ins_assur,
             N' | Evidence ', @ins_evid,
             N' | Evidence links ', @ins_link,
             N' | Practice/Statement mappings ', @ins_map, N'.');
END TRY
BEGIN CATCH
  IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  THROW;
END CATCH
GO

-- ---------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------
-- Obligations by type. Expect State 251, Execution 291, Assurance 16.
SELECT tm.type_name, COUNT(*) AS obligations
FROM GRAC_New.requirement_obligation ro
JOIN GRAC_New.obligation_type_master tm ON tm.obligation_type_id = ro.obligation_type_id
WHERE ro.status = N'Active'
  AND EXISTS(SELECT 1 FROM GRAC_New.audit_trace_event ae
             WHERE ae.entity_type = N'obligations' AND ae.entity_id = ro.obligation_id
               AND ae.remarks LIKE N'Bulk load: migration 054%')
GROUP BY tm.type_name
ORDER BY tm.type_name;
GO

-- Every loaded Obligation should have exactly one detail row, one evidence
-- spec and one Practice mapping. Rows returned here are gaps -- an empty
-- result set is the pass condition.
SELECT ro.obligation_id, ro.obligation_name, tm.type_name,
       x.detail_rows, x.evidence_rows, x.mapping_rows
FROM GRAC_New.requirement_obligation ro
JOIN GRAC_New.obligation_type_master tm ON tm.obligation_type_id = ro.obligation_type_id
CROSS APPLY (SELECT
    detail_rows = CASE tm.type_code
        WHEN N'State'     THEN (SELECT COUNT(*) FROM GRAC_New.obligation_state_rule d     WHERE d.obligation_id = ro.obligation_id AND d.status = N'Active')
        WHEN N'Execution' THEN (SELECT COUNT(*) FROM GRAC_New.obligation_execution_spec d WHERE d.obligation_id = ro.obligation_id AND d.status = N'Active')
        ELSE                   (SELECT COUNT(*) FROM GRAC_New.obligation_assurance_spec d WHERE d.obligation_id = ro.obligation_id AND d.status = N'Active') END,
    evidence_rows = (SELECT COUNT(*) FROM GRAC_New.requirement_obligation_evidence d    WHERE d.obligation_id = ro.obligation_id AND d.status = N'Active'),
    mapping_rows  = (SELECT COUNT(*) FROM GRAC_New.obligation_requirement_release_map d WHERE d.obligation_id = ro.obligation_id AND d.status = N'Active')) x
WHERE ro.status = N'Active'
  AND EXISTS(SELECT 1 FROM GRAC_New.audit_trace_event ae
             WHERE ae.entity_type = N'obligations' AND ae.entity_id = ro.obligation_id
               AND ae.remarks LIKE N'Bulk load: migration 054%')
  AND (x.detail_rows <> 1 OR x.evidence_rows <> 1 OR x.mapping_rows <> 1)
ORDER BY ro.obligation_id;
GO

-- Assurance trigger classification. Expect Scheduled 13 with no event,
-- EventDriven 3 each carrying one.
SELECT s.trigger_mode,
       COUNT(*)                                              AS specs,
       SUM(CASE WHEN s.event_type_id IS NULL THEN 1 ELSE 0 END) AS without_event,
       SUM(CASE WHEN s.event_type_id IS NULL THEN 0 ELSE 1 END) AS with_event
FROM GRAC_New.obligation_assurance_spec s
JOIN GRAC_New.requirement_obligation ro ON ro.obligation_id = s.obligation_id
WHERE s.status = N'Active'
  AND EXISTS(SELECT 1 FROM GRAC_New.audit_trace_event ae
             WHERE ae.entity_type = N'obligations' AND ae.entity_id = ro.obligation_id
               AND ae.remarks LIKE N'Bulk load: migration 054%')
GROUP BY s.trigger_mode
ORDER BY s.trigger_mode;
GO
